package com.metabuild.modules.admin.dashboard.controller;
import com.metabuild.admin.api.security.RequiresPermissions;import com.metabuild.modules.admin.auth.api.CurrentAuthorizationProvider;import com.metabuild.modules.admin.dashboard.application.DashboardRepository;import com.metabuild.shared.kernel.BadRequest;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/dashboard") public final class DashboardController {private final DashboardRepository repository;private final CurrentAuthorizationProvider current;public DashboardController(DashboardRepository repository,CurrentAuthorizationProvider current){this.repository=repository;this.current=current;}@GetMapping("/overview") @RequiresPermissions(codes="dashboard:overview:view") public Map<String,Object> overview(@RequestParam(defaultValue="6")int months){if(!Set.of(1,3,6,12).contains(months))throw new BadRequest(()->"dashboard.range.invalid","Range must be 1, 3, 6 or 12 months");return repository.overview(current.current().userId(),months);}}
